package br.com.jucelio.sentinelops.incident;
import br.com.jucelio.sentinelops.agent.*;import br.com.jucelio.sentinelops.incident.api.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service public class IncidentService{private final IncidentRepository repository;private final IncidentAgent agent;public IncidentService(IncidentRepository repository,IncidentAgent agent){this.repository=repository;this.agent=agent;}@Transactional public IncidentResponse create(IncidentRequest r){return IncidentResponse.from(repository.save(new Incident(r.title(),r.description(),r.serviceName(),r.severity())));}@Transactional(readOnly=true) public List<IncidentResponse> findAll(){return repository.findAll().stream().map(IncidentResponse::from).toList();}@Transactional(readOnly=true) public IncidentResponse findById(Long id){return IncidentResponse.from(get(id));}@Transactional public IncidentResponse changeStatus(Long id,IncidentStatus status){Incident i=get(id);i.changeStatus(status);return IncidentResponse.from(i);}@Transactional public InvestigationResult investigate(Long id){Incident i=get(id);i.changeStatus(IncidentStatus.INVESTIGATING);return agent.investigate(i);}private Incident get(Long id){return repository.findById(id).orElseThrow(()->new IncidentNotFoundException(id));}}
